class FarmDestinationTests{
 static void C(bool value,string message){if(!value)throw new Exception(message);}static ConcurrentDictionary<string,NativeJob> Jobs=(ConcurrentDictionary<string,NativeJob>)typeof(NativeBackend).GetField("jobs",BindingFlags.NonPublic|BindingFlags.Static).GetValue(null);
