   job.FarmArrived=true;job.GameAutoWanted=true;job.FarmQuietZone=true;job.FarmZoneCheckAt=DateTime.UtcNow.AddMinutes(-10);C(!NativeBackend.BeginFarmZoneRecheck(job,DateTime.UtcNow),"quiet-zone recheck overrode fixed zone");C(NativeBackend.BeginFixedFarmZoneRecheck(job,DateTime.UtcNow)&&job.FarmZoneWaiting&&job.FarmArrived&&job.GameAutoWanted,"fixed-zone drift did not recover or disabled existing idle");
   NativeBackend.StopMapFarm(job.Id);job.FarmPositionMap=69;job.FarmPositionX=555;job.FarmPositionY=444;job.FarmPositionReadAt=DateTime.UtcNow;job.ZoneId=0;job.ZoneReadAt=DateTime.UtcNow;job.FarmObserved=new FarmSpot[0];var reference=NativeBackend.GetReferenceFarmSpot(job.Id);C(reference.MapId==69&&reference.MapName=="Làng Mây"&&reference.Zone==0&&reference.X==555,"village reference or zone zero lost");job.ZoneReadAt=DateTime.UtcNow.AddSeconds(-10);C(NativeBackend.GetReferenceFarmSpot(job.Id).Zone==-1,"stale reference zone saved");job.FarmPositionReadAt=DateTime.UtcNow.AddSeconds(-20);bool rejected=false;try{NativeBackend.GetReferenceFarmSpot(job.Id);}catch{rejected=true;}C(rejected,"stale village coordinates accepted");
  }finally{NativeJob removed;Jobs.TryRemove(job.Id,out removed);}
